@@ -3296,22 +3271,21 @@
       exc->opcode = exc->code[exc->IP];

       exc->length = opcode_length[exc->opcode];
       if ( exc->length < 0 )
       {
         if ( exc->IP + 1 >= exc->codeSize )
           goto Fail_Overflow;
         exc->length = 2 - exc->length * exc->code[exc->IP + 1];
       }

-      if ( exc->IP + exc->length <= exc->codeSize )
-        return SUCCESS;
+      return SUCCESS;
     }

   Fail_Overflow:
     exc->error = FT_THROW( Code_Overflow );
     return FAILURE;
   }


   /**************************************************************************
    *
@@ -3847,122 +3821,163 @@
   /**************************************************************************
    *
    * NPUSHB[]:     PUSH N Bytes
    * Opcode range: 0x40
    * Stack:        --> uint32...
    */
   static void
   Ins_NPUSHB( TT_ExecContext  exc,
               FT_Long*        args )
   {
-    FT_UShort  L, K;
+    FT_Long  IP = exc->IP;
+    FT_Int   L, K;


-    L = (FT_UShort)exc->code[exc->IP + 1];
+    if ( ++IP >= exc->codeSize )
+    {
+      exc->error = FT_THROW( Code_Overflow );
+      return;
+    }
+
+    L = exc->code[IP];
+
+    if ( IP + L >= exc->codeSize )
+    {
+      exc->error = FT_THROW( Code_Overflow );
+      return;
+    }

     if ( BOUNDS( L, exc->stackSize + 1 - exc->top ) )
     {
       exc->error = FT_THROW( Stack_Overflow );
       return;
     }

-    for ( K = 1; K <= L; K++ )
-      args[K - 1] = exc->code[exc->IP + K + 1];
+    for ( K = 0; K < L; K++ )
+      args[K] = exc->code[++IP];

     exc->new_top += L;
+    exc->IP       = IP;
   }


   /**************************************************************************
    *
    * NPUSHW[]:     PUSH N Words
    * Opcode range: 0x41
    * Stack:        --> int32...
    */
   static void
   Ins_NPUSHW( TT_ExecContext  exc,
               FT_Long*        args )
   {
-    FT_UShort  L, K;
+    FT_Long  IP = exc->IP;
+    FT_Int   L, K;
+
+
+    if ( ++IP >= exc->codeSize )
+    {
+      exc->error = FT_THROW( Code_Overflow );
+      return;
+    }

+    L = exc->code[IP];

-    L = (FT_UShort)exc->code[exc->IP + 1];
+    if ( IP + 2 * L >= exc->codeSize )
+    {
+      exc->error = FT_THROW( Code_Overflow );
+      return;
+    }

     if ( BOUNDS( L, exc->stackSize + 1 - exc->top ) )
     {
       exc->error = FT_THROW( Stack_Overflow );
       return;
     }

-    exc->IP += 2;
+    /* note casting for sign-extension */
+    for ( K = 0; K < L; K++, IP += 2 )
+      args[K] = (FT_Short)( exc->code[IP + 1] << 8 ) | exc->code[IP + 2];

-    for ( K = 0; K < L; K++ )
-      args[K] = GetShortIns( exc );
-
-    exc->length   = 0;
     exc->new_top += L;
+    exc->IP       = IP;
   }


