+/****************************************************************************
+ *
+ * afgsub.c
+ *
+ *   Auto-fitter routines to parse the GSUB table (body).
+ *
+ * Copyright (C) 2025 by
+ * David Turner, Robert Wilhelm, and Werner Lemberg.
+ *
