+    /* We completely ignore GPOS script information      */
+    /* and collect lookup tables of all 'kern' features. */
+    while ( p < limit )
+    {
+      FT_ULong  featureTag    = FT_NEXT_ULONG( p );
+      FT_UInt   featureOffset = FT_NEXT_USHORT( p );
