+
+      if ( featureTag == TTAG_kern )
+      {
+        if ( !tt_face_validate_feature( table + featureOffset,
+                                        table_limit,
+                                        use_lookup_table_size,
+                                        use_lookup_table ) )
+          return FALSE;
+      }
+    }
