+    valueFormat1 = FT_NEXT_USHORT( p );
+    valueFormat2 = FT_NEXT_USHORT( p );
+    if ( valueFormat1 == 0x4 && valueFormat2 == 0 )
+    {
+      FT_Byte*  class_def1;
+      FT_Byte*  class_def2;
+      FT_UInt   class1Count;
+      FT_UInt   class2Count;
+
+      FT_UInt  max_size;
