+      {
+        FT_UInt  mid          = min + ( max - min ) / 2;
+        FT_UInt  startGlyphID = FT_PEEK_USHORT( p + mid * 6 );
+        FT_UInt  endGlyphID   = FT_PEEK_USHORT( p + mid * 6 + 2 );
