static void
af_move_contour_vertically( AF_Point  contour,
                            FT_Int    movement )
{
  AF_Point  point       = contour;
  AF_Point  first_point = point;


  if ( point )
  {
    do
    {
      point->y += movement;
      point     = point->next;

    } while ( point != first_point );
  }
}

